13	const NAME_KEY: Record<ImpactKey, string> = { dragon: 'bridgeDragon', thuanPhuoc: 'bridgeTp', tranThiLy: 'bridgeTtl', songHan: 'bridgeSh', hanTunnel: 'bridgeHr' };
14	const cm = (m: number) => (m * 100).toFixed(1);
15	
16	/* Thời tiết: chọn preset (Hiện trạng / Nắng hè / Mưa / Gió mùa / Bão), thanh cường độ 0–100 %, thẻ "Ảnh hưởng tới cầu" (vẽ lại 2 lần/giây khi đang mở) */
17	export function setupWeatherUI(toggle: Toggle) {
18	  const sel = document.getElementById('weatherSel') as HTMLSelectElement, k = document.getElementById('weatherK') as HTMLInputElement, val = document.getElementById('weatherKVal');
19	  const card = document.getElementById('wxImpact');
20	  const showK = () => { val.textContent = `${k.value}%`; };
21	  sel.addEventListener('change', () => getWeather()?.setPreset(sel.value as PresetName));
22	  k.addEventListener('input', () => { showK(); getWeather()?.setIntensity(Number(k.value) / 100); });
23	  showK();
24	
25	  let sig = '', timer = 0;
26	  const div = (cls: string, text?: string) => { const d = document.createElement('div'); d.className = cls; if (text !== undefined) d.textContent = text; return d; };
27	  /* Mỗi công trình một ô: tên + trạng thái lưu thông, gió tại mặt cầu (m/s, cấp), hiệu ứng chính. Chỉ dựng lại DOM khi nội dung đổi. */
28	  const render = () => {
29	    const w = getWeather(); if (!w) return;
30	    const rows = w.impact().map((r) => {
31	      const lines: string[] = [];
32	      if (r.key === 'hanTunnel') lines.push(t('wxTunnelOk'));
33	      else {
34	        let wind = t('wxWindDeck', { v: r.windDeck.toFixed(1), b: r.level });
35	        if (r.windTop > 0) wind += ' · ' + t('wxWindTop', { v: r.windTop.toFixed(1) });
36	        lines.push(wind);
37	        if (r.effects.includes('rainWindCable')) lines.push(t('wxRainWind'));
38	        if (r.effects.includes('thermal')) lines.push(t('wxThermal', { cm: cm(r.expand) }));
39	        if (r.sag > 0.005) lines.push(t('wxSag', { cm: cm(r.sag) }));
40	        if (r.effects.includes('swingLocked')) lines.push(t('wxSwingBlocked'));
41	        if (r.status === 'closed') lines.push(t('wxClosedNote'));
42	      }
43	      return { key: r.key, status: r.status, lines };
44	    });
45	    const next = JSON.stringify(rows);
46	    if (next === sig) return;
47	    sig = next;
48	    card.replaceChildren(...rows.map((r) => {
49	      const item = div('wx-item'), head = div('wx-head'), st = div('wx-st ' + r.status, t(r.status === 'closed' ? 'wxClosed' : 'wxOpen'));
50	      head.append(div('', t(NAME_KEY[r.key])), st);
51	      item.append(head, ...r.lines.map((l, i) => div(i === 0 && r.key !== 'hanTunnel' ? 'wx-wind' : '', l)));
52	      return item;
53	    }), div('wx-note', t('wxImpactNote', { k: CONFIG.weather.swayExaggeration })));
54	  };
55	  setupScenarioUI();
56	  toggle('btnWxImpact', (on) => {
57	    card.hidden = !on; clearInterval(timer);
58	    if (on) { sig = ''; render(); timer = window.setInterval(render, 500); }
59	  });
60	  onChange(() => { sig = ''; if (!card.hidden) render(); });
61	}
62	
63	/* Kịch bản bão (mục 6): nút bật/dừng, khung chú thích wxS1…wxS8, thanh tiến độ. Camera bay theo hành trình kịch bản (chế độ 'storm') cho tới khi người xem kéo chuột, cuộn,
64	   nhấn Esc hoặc chọn góc nhìn — khi đó chỉ camera được trả lại, thời tiết vẫn chạy hết (giống exitTour). Nút "Dừng kịch bản" trả ngay preset cũ. */
65	function setupScenarioUI() {
66	  const btn = document.getElementById('btnWxStorm'), box = document.getElementById('wxScenario'), text = document.getElementById('wxScenarioText');
67	  const time = document.getElementById('wxScenarioTime'), bar = document.getElementById('wxScenarioBar');
68	  const sc = () => getWeather()?.scenario;
69	  let capKey: string | null = null, timer = 0;
70	  const label = () => { btn.textContent = t(sc()?.running ? 'wxStormStop' : 'wxStormRun'); };
71	  const showCap = () => { text.textContent = capKey ? t(capKey, { k: CONFIG.weather.swayExaggeration }) : ''; };
72	  /* Giọng đọc mốc hiện tại (clip wxStorm-<mốc>, `npm run gen:voice`). Đang xem Tour thì nhường giọng cho Tour. Lời đọc mốc 4 nói cố định "hai mươi lần" = swayExaggeration */
73	  const speak = () => { const s = sc(); if (s?.running && capKey && !document.body.classList.contains('touring')) narration.play('wxStorm', s.step); };
74	  const clock = () => {
75	    const s = sc(); if (!s) return;
76	    const mmss = (v: number) => `${Math.floor(v / 60)}:${String(Math.floor(v % 60)).padStart(2, '0')}`, tt = Math.min(s.t, s.duration);   // độ dài thật: kéo dài theo giọng đọc
77	    time.textContent = `${mmss(tt)} / ${mmss(s.duration)}`; bar.style.width = `${(tt / s.duration * 100).toFixed(1)}%`;
78	  };
79	  const wire = () => {
80	    const s = sc(); if (!s) return;
81	    s.on.caption = (key) => { capKey = key; showCap(); if (key) speak(); else narration.stop(); };
82	    s.on.end = () => { clearInterval(timer); box.hidden = true; document.body.classList.remove('wxrun'); btn.setAttribute('aria-pressed', 'false'); label(); };
83	  };
84	  btn.addEventListener('click', () => {
85	    const s = sc(); if (!s) return;
86	    wire();
87	    if (s.running) { s.stop(true); return; }
88	    exitTour(); narration.stop(); s.start({ from: { pos: camera.position, target: controls.target } }); followScenario();
89	    box.hidden = false; document.body.classList.add('wxrun'); btn.setAttribute('aria-pressed', 'true'); label(); clock();
90	    clearInterval(timer); timer = window.setInterval(clock, 250);
91	  });
92	  const release = () => { if (!sc()?.running) return; sc().releaseCamera(); if (cam.mode === 'storm') { cam.mode = 'orbit'; controls.enabled = true; } };   // trả ngay để thao tác kéo đầu tiên đã điều khiển được
93	  canvas.addEventListener('pointerdown', release);
94	  canvas.addEventListener('wheel', release, { passive: true });
95	  window.addEventListener('keydown', (e) => { if (e.key === 'Escape') release(); });
96	  document.querySelectorAll('[data-view]').forEach((b) => b.addEventListener('click', release));
97	  label();
98	  // Đổi ngôn ngữ / bật giọng: đọc lại mốc hiện tại (đăng ký sau Tour — syncNarration của Tour dừng giọng khi không ở chế độ Tour)
99	  onChange(() => { label(); showCap(); speak(); });
100	  narration.onChange(speak);
101	}
