1	import { CONFIG } from '../config';
2	import { onChange } from '../i18n';
3	
4	/* ===== Chế độ gọn (điện thoại): body.compact + hai tờ Cài đặt / Góc nhìn (body.sheet-*) =====
5	   Máy tính dùng chung trạng thái tờ (bảng thu gọn thành nút ⚙ / ☰, D-025). */
6	export type Sheet = 'none' | 'settings' | 'views';
7	
8	export const ui: { compact: boolean; sheet: Sheet } = { compact: false, sheet: 'none' };
9	
10	/* Mỗi lúc chỉ một tờ mở; 'none' = đóng hết. aria-expanded của hai nút mở tờ theo trạng thái */
11	export function openSheet(s: Sheet) {
12	  // Đóng một tờ khi focus còn bên trong: đưa focus về nút mở tờ đó, không để kẹt trên ô chọn đã ẩn (mũi tên sẽ đổi cài đặt thay vì lái dù)
13	  const SHEET: Record<Sheet, [string, string] | null> = { none: null, settings: ['.brand', 'btnSettings'], views: ['.views', 'btnViewsSheet'] };   // [khung tờ, nút mở]
14	  const prev = SHEET[ui.sheet], back = ui.sheet !== s && prev && document.activeElement?.closest(prev[0]) ? prev[1] : '';
15	  ui.sheet = s;
16	  document.body.classList.toggle('sheet-settings', s === 'settings');
17	  document.body.classList.toggle('sheet-views', s === 'views');
18	  document.getElementById('btnSettings')?.setAttribute('aria-expanded', String(s === 'settings'));
19	  document.getElementById('btnViewsSheet')?.setAttribute('aria-expanded', String(s === 'views'));
20	  if (back) document.getElementById(back)?.focus({ preventScroll: true });
21	}
22	
23	export function closeSheets() { openSheet('none'); }
24	
25	/* Đưa phần tử vào tầm nhìn: mở đúng tờ chứa nó (test và phím tắt dùng); phần tử ngoài hai tờ thì đóng hết.
26	   Điện thoại: chip .seg, nút Tour 4 cầu nằm trên thanh dưới (ngoài tờ); máy tính: cả .views là bảng thu gọn */
27	export function reveal(el: Element | null) {
28	  if (!el) return;
29	  if (el.closest('.brand')) openSheet('settings');
30	  else if (el.closest('.view-list') || (!ui.compact && el.closest('.views'))) openSheet('views');
31	  else closeSheets();
32	}
33	
34	/* Nút mở/đóng tờ; chạm khung 3D, chọn góc nhìn, Esc thì đóng; ghi --bar-h (cao thanh dưới) cho khung chú thích Tour / Kịch bản bão */
35	function wireSheets() {
36	  const toggle = (s: Sheet) => () => openSheet(ui.sheet === s ? 'none' : s);   // bấm lại thì đóng
37	  document.getElementById('btnSettings')?.addEventListener('click', toggle('settings'));
38	  document.getElementById('btnViewsSheet')?.addEventListener('click', toggle('views'));
39	  document.querySelectorAll('.sheet-close').forEach((b) => b.addEventListener('click', () => closeSheets()));
40	  // Bấm khung 3D khi có tờ mở: chỉ đóng tờ. Pha capture trên window chạy trước listener của canvas (exitTour, OrbitControls) nên chặn được cú bấm này
41	  window.addEventListener('pointerdown', (e) => {
42	    if (ui.sheet === 'none' || (e.target as Element | null)?.id !== 'scene') return;
43	    closeSheets(); e.stopPropagation(); e.preventDefault();
44	  }, true);
45	  document.querySelectorAll('[data-view]').forEach((b) => b.addEventListener('click', () => { if (ui.sheet !== 'none') closeSheets(); }));
46	  // Esc khi có tờ mở: chỉ đóng tờ, chặn các listener Esc khác (thoát Tour, xuống cabin, thoát bay); Esc lần sau mới tới chúng
47	  window.addEventListener('keydown', (e) => {
48	    if (e.key !== 'Escape' || ui.sheet === 'none') return;
49	    closeSheets(); e.stopImmediatePropagation(); e.preventDefault();
50	  }, true);
51	  const bar = document.querySelector<HTMLElement>('.views');
52	  if (!bar || typeof ResizeObserver === 'undefined') return;
53	  // chỉ đo lúc thanh đóng: tờ Góc nhìn làm .views cao lên, tờ Cài đặt ẩn .views
54	  new ResizeObserver(() => { if (ui.compact && ui.sheet === 'none') document.documentElement.style.setProperty('--bar-h', bar.offsetHeight + 'px'); }).observe(bar);
55	}
56	
57	/* Vệt mờ trên hàng chip .seg: .more-start / .more-end khi còn nội dung bị cuộn khuất ở đầu / cuối dòng (RTL: scrollLeft ≤ 0, đầu dòng ở bên phải) */
58	function wireSegFade() {
59	  const seg = document.querySelector<HTMLElement>('.seg');
60	  if (!seg) return;
61	  const update = () => {
62	    const max = seg.scrollWidth - seg.clientWidth;
63	    const pos = Math.abs(seg.scrollLeft);   // quãng đã cuộn từ đầu dòng, đúng cả LTR lẫn RTL
64	    seg.classList.toggle('more-start', ui.compact && pos > 8);
65	    seg.classList.toggle('more-end', ui.compact && max - pos > 8);
66	  };
67	  seg.addEventListener('scroll', update, { passive: true });
68	  window.addEventListener('resize', update);
69	  segFadeUpdate = update;
70	  if (typeof ResizeObserver !== 'undefined') new ResizeObserver(update).observe(seg);
71	  onChange(update);   // đổi ngôn ngữ đổi bề rộng chip nhưng không đổi hộp .seg nên ResizeObserver không báo
72	}
73	let segFadeUpdate = () => {};
74	
75	/* Tour / kịch bản bão bật lên thì đóng tờ đang mở (class của body đổi) */
76	function wireAutoClose() {
77	  let was = false;
78	  new MutationObserver(() => {
79	    const on = document.body.classList.contains('touring') || document.body.classList.contains('wxrun');
80	    if (on && !was && ui.sheet !== 'none') closeSheets();
81	    was = on;
82	  }).observe(document.body, { attributes: true, attributeFilter: ['class'] });
83	}
84	
85	export function setupCompactUI() {
86	  wireSheets();
87	  wireSegFade();
88	  wireAutoClose();
89	  const mq = window.matchMedia(CONFIG.ui.compactQuery);
90	  const apply = () => {
91	    const was = ui.compact;
92	    ui.compact = mq.matches;
93	    document.body.classList.toggle('compact', ui.compact);
94	    if (was !== ui.compact) closeSheets();   // qua ngưỡng gọn ↔ máy tính (cả hai chiều): không để tờ mở dở
95	    segFadeUpdate();
96	  };
97	  mq.addEventListener('change', apply);
98	  apply();
99	}
